# ============================================================
# StableVAE 主类
# ============================================================

class StableVAE(AutoEncoderBase):
    """
    波形域变分自编码器。

    架构:
        输入波形 [B, 1, T_wave]
            ↓ Encoder (4个下采样块, stride 乘积=480)
        编码器输出 [B, 2*latent_dim, T_lat]  (mean + scale)
            ↓ VAEBottleneck (重参数化)
        潜在表示 z [B, latent_dim, T_lat]   ← 扩散模型在此操作
            ↓ Decoder (4个上采样块)
        重建波形 [B, 1, T_wave]

    典型配置 (24kHz, 下采样率480):
        - latent_dim: 128
        - 潜在帧率: 24000 / 480 = 50 Hz
        - strides: [2, 4, 5, 12]  或其他组合，乘积=480
    """
    def __init__(
        self,
        encoder: OobleckEncoder,
        decoder: OobleckDecoder,
        latent_dim: int,
        downsampling_ratio: int,
        sample_rate: int,
        io_channels: int = 2,
        bottleneck: Bottleneck = None,
        pretransform: Pretransform = None,
        in_channels: int = None,
        out_channels: int = None,
        soft_clip: bool = False,
    ):
        AutoEncoderBase.__init__(
            self,
            downsampling_ratio=downsampling_ratio,
            sample_rate=sample_rate,
            latent_shape=(latent_dim, None)
        )

        self.latent_dim = latent_dim
        self.io_channels = io_channels
        self.in_channels = io_channels
        self.out_channels = io_channels
        self.min_length = self.downsampling_ratio

        if in_channels is not None:
            self.in_channels = in_channels
        if out_channels is not None:
            self.out_channels = out_channels

        self.bottleneck = bottleneck
        self.encoder = encoder
        self.decoder = decoder
        self.pretransform = pretransform
        self.soft_clip = soft_clip
        self.is_discrete = self.bottleneck is not None and self.bottleneck.is_discrete

    def encode(
        self, waveform: torch.Tensor, waveform_lengths: torch.Tensor,
        pad_latent_len: int = 500
    ) -> tuple[torch.Tensor, torch.Tensor]:
        """
        将波形编码到潜在空间。

        Args:
            waveform: [B, C, T_wave] 波形
            waveform_lengths: [B] 每段波形的有效长度
            pad_latent_len: 填充到的潜在长度

        Returns:
            z: [B, latent_dim, pad_latent_len] 潜在表示
            z_mask: [B, pad_latent_len] 有效掩码 (1=有效, 0=填充)
        """
        z = self.encoder(waveform)
        z = self.bottleneck.encode(z)
        z_length = waveform_lengths // self.downsampling_ratio
        z_mask = create_mask_from_length(z_length, max_length=pad_latent_len)

        B, C, L = z.shape
        if L < pad_latent_len:
            pad_size = pad_latent_len - L
            z = torch.cat([z, torch.zeros(B, C, pad_size, device=z.device, dtype=z.dtype)], dim=-1)
        return z, z_mask

    def decode(self, latents: torch.Tensor, latent_mask: torch.Tensor | None = None) -> torch.Tensor:
        """
        将潜在表示解码回波形。

        Args:
            latents: [B, C, T_latent] 潜在表示
            latent_mask: [B, T_latent] 可选掩码，1=有效，0=padding

        Returns:
            waveform: [B, C, T_wave] 重建波形
        """
        if latent_mask is not None:
            outputs = []
            for b in range(latents.size(0)):
                valid_idx = latent_mask[b].bool()
                valid_latents = latents[b, :, valid_idx]  # [C, T_valid]
                outputs.append(self.decoder(valid_latents.unsqueeze(0)))
            return torch.cat(outputs, dim=0)
        else:
            return self.decoder(latents)


# ============================================================
# VAE 投影包装器 (用于 audio_encoder 路径)
# ============================================================

class StableVAEProjectorWrapper(nn.Module):
    """
    将 VAE 编码器输出投影到指定维度，作为 time_aligned_context。
    在 audio_editing 任务中，源音频的 VAE 潜在通过此包装器后
    与噪声潜在沿通道拼接，注入到 DiT 中。
    """
    def __init__(
        self,
        vae_dim: int,
        embed_dim: int,
        model: StableVAE | None = None,
    ):
        super().__init__()
        self.model = model
        self.proj = nn.Linear(vae_dim, embed_dim)

    def forward(
        self, waveform: torch.Tensor, waveform_lengths: torch.Tensor
    ) -> tuple[torch.Tensor, torch.Tensor]:
        self.model.eval()
        with torch.no_grad():
            z, z_mask = self.model.encode(waveform, waveform_lengths, pad_latent_len=500)
        z = self.proj(z.transpose(1, 2))  # [B, T, embed_dim]
        return {"output": z, "mask": z_mask}


# ============================================================
# 工具函数 (从 utils.torch_utilities 引入)
# ============================================================

def create_mask_from_length(lengths: torch.Tensor, max_length: int = None) -> torch.Tensor:
    """根据长度序列生成掩码 [B, max_len]"""
    if max_length is None:
        max_length = lengths.max().item()
    batch_size = lengths.shape[0]
    mask = torch.arange(max_length, device=lengths.device).unsqueeze(0).expand(batch_size, -1)
    mask = mask < lengths.unsqueeze(1)
    return mask.float()


# ============================================================
# 辅助：移除 state_dict 前缀
# ============================================================

def remove_key_prefix_factory(prefix: str):
    def remove_key_prefix(model_dict, state_dict):
        new_state_dict = {}
        for k, v in state_dict.items():
            if k.startswith(prefix):
                new_k = k[len(prefix):]
                if new_k in model_dict:
                    new_state_dict[new_k] = v
        return new_state_dict
    return remove_key_prefix
